// Regenerates one Code Connect template per Lemonade icon, per platform.
//
//   node scripts/generate-icon-templates.mjs            # both targets
//   node scripts/generate-icon-templates.mjs compose    # one target
//
// Reads icons.manifest.json (kebab-case Figma name -> node id, refreshed from
// Figma) and cross-checks every entry against the platform's icon enum, which is
// itself generated by svg-asset-converter.main.kts. If the two have drifted the
// script fails rather than emitting templates that point at icons the enum does
// not have.
//
// Every target must be generated and published. Figma resolves a nested icon by
// node, and when a label has no template for that node it falls back to another
// label's — so a missing SwiftUI icon does not render as a blank, it renders the
// Kotlin snippet inside a Swift call.

import { readFileSync, writeFileSync, mkdirSync, rmSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..')
const repo = join(root, '..')

const pascal = (name) =>
  name
    .split(/[-_ ]+/)
    .filter(Boolean)
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join('')

const TARGETS = {
  compose: {
    outDir: 'connect/icons',
    enumPath: 'kmp/core/src/commonMain/kotlin/com/teya/lemonade/core/LemonadeIcons.kt',
    // Kotlin entries carry no raw value; the name is the kebab name in Pascal case.
    members: (src) =>
      new Map([...src.matchAll(/^\s+([A-Z][A-Za-z0-9]*),/gm)].map((m) => [m[1], m[1]])),
    memberFor: (name) => pascal(name),
    reference: (member) => `LemonadeIcons.${member}`,
    imports: ["'import com.teya.lemonade.core.LemonadeIcons'"],
    tag: 'kotlin',
    fileName: (name) => `${pascal(name)}.figma.ts`,
  },
  swiftui: {
    outDir: 'connect-swiftui/icons',
    enumPath: 'swiftui/Sources/Lemonade/LemonadeIcons.swift',
    // Swift cases carry the kebab name as their raw value, so the mapping is
    // read straight off the enum instead of being re-derived.
    members: (src) =>
      new Map(
        [...src.matchAll(/^\s+case ([A-Za-z][A-Za-z0-9]*) = "([^"]+)"/gm)].map((m) => [m[2], m[1]]),
      ),
    memberFor: (name, members) => members.get(name),
    reference: (member) => `LemonadeIcon.${member}`,
    imports: [],
    tag: 'swift',
    fileName: (name, member) => `${member[0].toUpperCase()}${member.slice(1)}.figma.ts`,
  },
}

const manifest = JSON.parse(readFileSync(join(root, 'icons.manifest.json'), 'utf8'))
const requested = process.argv.slice(2)
const targets = requested.length ? requested : Object.keys(TARGETS)

for (const name of targets) {
  if (!TARGETS[name]) {
    console.error(`Unknown target "${name}". Known: ${Object.keys(TARGETS).join(', ')}`)
    process.exit(1)
  }
}

for (const targetName of targets) {
  const target = TARGETS[targetName]
  const enumSource = readFileSync(join(repo, target.enumPath), 'utf8')
  const members = target.members(enumSource)
  const known = new Set(members.values())

  const missing = []
  for (const iconName of Object.keys(manifest.icons)) {
    const member = target.memberFor(iconName, members)
    if (!member || !known.has(member)) missing.push(iconName)
  }
  if (missing.length) {
    console.error(`[${targetName}] ${missing.length} Figma icon(s) have no enum entry:`)
    for (const n of missing) console.error(`  ${n}`)
    console.error(`\nRun the svg-asset-converter, or refresh icons.manifest.json from Figma.`)
    process.exit(1)
  }

  const outDir = join(root, target.outDir)
  rmSync(outDir, { recursive: true, force: true })
  mkdirSync(outDir, { recursive: true })

  for (const [iconName, nodeId] of Object.entries(manifest.icons)) {
    const member = target.memberFor(iconName, members)
    // Emits a bare enum reference, not a view/composable call: every consumer of
    // an icon takes the enum. Parents needing a rendered icon wrap it themselves.
    const body = `// url=<LEMONADE_ICONS>?node-id=${nodeId.replace(':', '-')}
// source=${target.enumPath}
// component=${target.reference(member).split('.')[0]}
import figma from 'figma'

export default {
  example: figma.${target.tag}\`${target.reference(member)}\`,${
    target.imports.length ? `\n  imports: [${target.imports.join(', ')}],` : ''
  }
  id: 'icon-${iconName}',
  metadata: { nestable: true },
}
`
    writeFileSync(join(outDir, target.fileName(iconName, member)), body)
  }

  console.log(`[${targetName}] generated ${readdirSync(outDir).length} templates in ${target.outDir}/`)
}
